#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void conv_relu_pool_kernel(
    const float* input, const float* weight, const float* bias,
    float* output, int batch, int in_channels, int out_channels, 
    int in_h, int in_w, int kernel_size, int pool_size
) {
    int out_conv_h = in_h - kernel_size + 1;
    int out_conv_w = in_w - kernel_size + 1;
    int pooled_h = out_conv_h / pool_size;
    int pooled_w = out_conv_w / pool_size;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * out_channels * pooled_h * pooled_w) return;

    int b = idx / (out_channels * pooled_h * pooled_w);
    int oc = (idx % (out_channels * pooled_h * pooled_w)) / (pooled_h * pooled_w);
    int ph = (idx % (pooled_h * pooled_w)) / pooled_w;
    int pw = idx % pooled_w;

    float max_val = -INFINITY;

    for (int dy = 0; dy < pool_size; ++dy) {
        for (int dx = 0; dx < pool_size; ++dx) {
            int conv_i = ph * pool_size + dy;
            int conv_j = pw * pool_size + dx;

            if (conv_i >= out_conv_h || conv_j >= out_conv_w) continue;

            float sum = bias[oc];
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int in_i = conv_i + kh;
                    int in_j = conv_j + kw;
                    if (in_i < in_h && in_j < in_w) {
                        for (int ic = 0; ic < in_channels; ++ic) {
                            int input_idx = b * in_channels * in_h * in_w + ic * in_h * in_w + in_i * in_w + in_j;
                            int weight_idx = oc * in_channels * kernel_size * kernel_size + ic * kernel_size * kernel_size + kh * kernel_size + kw;
                            sum += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
            }
            sum = fmaxf(sum, 0.0f);
            max_val = fmaxf(max_val, sum);
        }
    }
    output[idx] = max_val;
}

torch::Tensor conv_relu_pool_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, 
                                 int kernel_size, int pool_size) {
    auto out_conv_h = input.size(2) - kernel_size + 1;
    auto out_conv_w = input.size(3) - kernel_size + 1;

    auto out = torch::zeros({input.size(0), weight.size(0), out_conv_h/pool_size, out_conv_w/pool_size}, 
                           input.options());

    int threads = 256;
    int blocks = (out.numel() + threads - 1) / threads;

    hipLaunchKernelGGL(conv_relu_pool_kernel, blocks, threads, 0, 0,
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        out.data_ptr<float>(),
        input.size(0), input.size(1), weight.size(0),
        input.size(2), input.size(3), kernel_size, pool_size
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float xi = x[idx];
        float sqrt_2_over_pi = sqrtf(2.0f / M_PI);
        float cube = 0.044715f * xi * xi * xi;
        float tanh_inner = tanhf(sqrt_2_over_pi * (xi + cube));
        out[idx] = 0.5f * xi * (1.0f + tanh_inner);
    }
}

torch::Tensor gelu_forward(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    hipLaunchKernelGGL(gelu_kernel, num_blocks, block_size, 0, 0, x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
